new:
/* THE CARD'S LIFETIME IS THE SIM'S, NOT THE WALL CLOCK'S (r3 blocker).
   The card used to self-fade on `bi-out ... 3s forwards`, i.e. on REAL
   time, while the ringside freeze it belongs to runs on the sim's own
   encounter timer. Any client slower than the animation — a stall, a
   long GC, a SwiftShader capture — lost the marquee beat of the whole
   encounter while the freeze was still running underneath it. Now the
   host drives --bi-fade off `encounter.timeLeft`, so the card is up for
   exactly as long as the beat is, on any machine. */
#bossintro.show { display: block; opacity: var(--bi-fade, 1);
  animation: bi-in 0.45s ease-out; }

old:
#bossspot.on { display: block;
  animation: spot-in 0.5s ease-out both, bi-out 0.5s ease 3s forwards; }
@keyframes spot-in { from { opacity: 0; transform: scale(0.8); } }

new:
#bossspot.on { display: block; opacity: var(--bi-fade, 1);
  animation: spot-in 0.5s ease-out; }
@keyframes spot-in {
  from { opacity: 0; transform: scale(0.8); }
  to { transform: scale(1); }
}
